def f(g):
    bg=g[0][0]
    col=next(v for row in g for v in row if v!=bg)
    pts=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==col]
    r0,r1=min(i for i,_ in pts),max(i for i,_ in pts)
    c0,c1=min(j for _,j in pts),max(j for _,j in pts)
    rowc={i:sum(1 for j in range(c0,c1+1) if g[i][j]==col) for i in range(r0,r1+1)}
    colc={j:sum(1 for i in range(r0,r1+1) if g[i][j]==col) for j in range(c0,c1+1)}
    W,H=c1-c0+1,r1-r0+1
    o=[row[:] for row in g]
